{%- elif n < 70 -%}{%- if n == 60 -%}soixante{%- elif n == 61 -%}soixante et un{%- else -%}soixante-{{ _w1(n-60) }}{%- endif -%}
{%- elif n < 80 -%}{%- if n == 70 -%}soixante-dix{%- elif n == 71 -%}soixante et onze{%- else -%}soixante-{{ _w20(n-60) }}{%- endif -%}
{%- elif n < 90 -%}{%- if n == 80 -%}quatre-vingts{%- else -%}quatre-vingt-{{ _w1(n-80) }}{%- endif -%}
{%- else -%}{%- if n == 90 -%}quatre-vingt-dix{%- else -%}quatre-vingt-{{ _w20(n-80) }}{%- endif -%}
{%- endif -%}
{%- endmacro -%}

{%- macro _w1000(n) -%}
{%- set n = n|int -%}
{%- set h = n // 100 -%}
{%- set r = n % 100 -%}
{%- if h > 0 -%}
    {%- if h == 1 -%}cent{%- if r > 0 %} {{ _w100(r) }}{%- endif -%}
    {%- else -%}{{ _w1(h) }} cent{%- if r > 0 %} {{ _w100(r) }}{%- else %}s{%- endif -%}
    {%- endif -%}
{%- else -%}{{ _w100(r) }}{%- endif -%}
{%- endmacro -%}

{%- macro montant_fr(amount) -%}
{%- set n = (amount or 0)|round(0)|int -%}
{%- if n == 0 -%}
    zéro franc CFA
{%- else -%}
    {%- set milliards = n // 1000000000 -%}
    {%- set reste1 = n % 1000000000 -%}
    {%- set millions = reste1 // 1000000 -%}
    {%- set reste2 = reste1 % 1000000 -%}
    {%- set mille = reste2 // 1000 -%}
    {%- set reste = reste2 % 1000 -%}
    {%- set p1 = (_w1000(milliards) ~ " milliards") if milliards > 1 else ("un milliard" if milliards == 1 else "") -%}
    {%- set p2 = (_w1000(millions) ~ " millions") if millions > 1 else ("un million" if millions == 1 else "") -%}
    {%- set p3 = (_w1000(mille) ~ " mille") if mille > 1 else ("mille" if mille == 1 else "") -%}
    {%- set p4 = _w1000(reste) if reste > 0 else "" -%}
    {%- set text = "" -%}
    {%- if p1 %}{%- set text = text ~ p1 ~ " " %}{%- endif -%}
    {%- if p2 %}{%- set text = text ~ p2 ~ " " %}{%- endif -%}
    {%- if p3 %}{%- set text = text ~ p3 ~ " " %}{%- endif -%}
    {%- if p4 %}{%- set text = text ~ p4 ~ " " %}{%- endif -%}
    {{- text | trim }} franc{%- if n > 1 -%}s{%- endif -%}
{%- endif -%}
{%- endmacro -%}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&display=swap');
    :root { --primary: #032A5F; --accent: #0756C5; }
    @page { size: A4; margin: 5mm 5mm 38mm 5mm; }

    .print-format {
        padding: 0 12px 60px 12px !important;
        font-size: 9.8px;
        line-height: 1.18;
        font-family: 'Montserrat', Arial, Helvetica, sans-serif;
        color: var(--primary);
    }

    label { color: var(--accent); font-size: 9px; margin-bottom: 1px; font-weight: 600; }
    .text-strong { font-weight: 700; color: var(--primary); }
    .small { font-size: 8.8px; color: var(--primary); }
    .desc { font-size: 8.8px; color: var(--primary); }

    h2.text-strong { 
        margin: 0 !important; 
        font-size: 12.5px; 
        text-transform: uppercase; 
        letter-spacing: 0.4px; 
    }

    table { width:100%; border-collapse: collapse; }
    .table-bordered { border: 1.2px solid var(--accent); }
    .table>thead>tr>th, .table>tbody>tr>td { 
        padding: 2px 4px; 
        line-height: 1.15; 
        vertical-align: top; 
    }
    .table>thead>tr>th { 
        background-color: var(--accent); 
        color: #fff; 
        font-weight: 600; 
        padding: 3px 4px; 
    }

    .box {
        border: 1.2px solid var(--accent);
        padding: 4px 6px;
        border-radius: 5px;
        background-color: #f8fbff;
    }

    .row-alt { background-color: #f8fbff; }
    .logo-cell { width: 180px; height: 90px; }

    .signature-box {
        position: fixed; bottom: 26mm; right: 5mm; width: 48%;
        border: 1.2px solid var(--accent); border-radius: 3px;
        padding: 3px 8px 4px; background-color: #f8fbff; z-index: 10;
    }
    .signature-box .signature-title {
        font-weight: 700; color: var(--accent); font-size: 8.5px;
        text-transform: uppercase; letter-spacing: 0.3px;
        border-bottom: 1px solid var(--accent); padding-bottom: 2px;
        margin-bottom: 3px; text-align: center;
    }
    .signature-space { height: 15px; border-bottom: 1px dashed var(--primary); margin-top: 2px; }

    .custom-footer {
        position: fixed; bottom: 0; left: 0; right: 0;
        color: var(--primary); font-size: 8.5px;
        border-top: 1.2px solid var(--accent);
        padding: 4px 6mm 3px 6mm; text-align: center; line-height: 1.3;
        background: #fff;
    }

    .terms-block { font-size: 8.5px; line-height: 1.25; margin-top: 5px; }
</style>

{% for page in layout %}
<div class="page-break">
    <div class="print-format">

        <!-- Titre -->
        <div class="row text-center">
            <h2 class="text-strong" {% if doc.is_return %}style="color:#dc2626;"{% endif %}>
                {{ _("Avoir") if doc.is_return else _("Facture de Vente") }}
            </h2>
        </div>

        {% if doc.is_return %}
        <div style="background:#fef2f2; border:1.5px solid #fecaca; border-radius:6px; padding:5px 12px; color:#991b1b; font-size:10px; font-weight:700; text-align:center; margin-bottom:8px;">
            Document de crédit {% if doc.return_against %}— Réf. : {{ doc.return_against }}{% endif %}
        </div>
        {% endif %}

        <!-- Logo -->
        <div class="row mb-10">
            <div class="col-xs-6 logo-cell">
                {% if logo_url %}
                    <img src="{{ logo_url }}" alt="logo" style="max-width:100%; max-height:100%;">
                {% endif %}
            </div>
        </div>

        <!-- En-tête infos société -->
        <div class="row mb-10">
            <div class="col-xs-7">
                <div><span class="text-strong">Société :</span> {{ company.company_name }}</div>
                <div><span class="text-strong">Adresse :</span> {{ co_addr_display }}</div>
                {% if company.tax_id %}<div><span class="text-strong">NCC :</span> {{ company.tax_id }}</div>{% endif %}
                {% if company.custom_regime_dimposition %}<div><span class="text-strong">Régime d'imposition :</span> {{ company.custom_regime_dimposition }}</div>{% endif %}
                <div><span class="text-strong">RCCM :</span> {{ rccm }}</div>
                <div class="small"><span class="text-strong">Interlocuteur :</span> {{ owner_fullname }}</div>
            </div>

            <div class="col-xs-5">
                <div class="mb-10">
                    <div><span class="text-strong">N° Facture :</span> {{ doc.name }}</div>
                </div>
                <div class="mb-10">
                    <div><span class="text-strong">Date :</span> {{ frappe.utils.format_date(doc.posting_date or doc.transaction_date, "dd MMMM yyyy") }}</div>
                </div>
                {% if doc.due_date %}
                    <div class="mb-10">
                        <div><span class="text-strong">Date d'échéance :</span> {{ frappe.utils.format_date(doc.due_date, "dd MMMM yyyy") }}</div>
                    </div>
                {% endif %}
                {% if doc.payment_terms_template or doc.custom_condition_de_réglement %}
                    <div class="mb-10">
                        <div><span class="text-strong">Conditions de règlement :</span> {{ doc.custom_condition_de_réglement or doc.payment_terms_template }}</div>
                    </div>
                {% endif %}
                <div><span class="text-strong">Devise :</span> {{ "Franc CFA" if doc.currency in ["XOF", "CFA", "FCFA"] else (doc.currency or "") }}</div>
            </div>
        </div>

        <!-- Adresse de facturation -->
        <div class="row mb-10" style="display: flex;">
            <div class="col-xs-6 pl-4" style="margin-left: auto;">
                <div class="box">
                    <div class="text-strong" style="margin-bottom:2px;">Adresse de facturation :</div>

                    <div class="small"><strong>Nom :</strong> {{ doc.customer_name or doc.party_name }}</div>

                    {% if billing_addr %}
                        {% if billing_addr.address_line1 or billing_addr.address_line2 %}
                            <div class="small"><strong>Adresse :</strong> {{ billing_addr.address_line1 or "" }} {{ billing_addr.address_line2 or "" }}</div>
                        {% endif %}
                        {% if billing_addr.city or billing_addr.country %}
                            <div class="small"><strong>Ville / Pays :</strong> {{ billing_addr.city or "" }} {{ billing_addr.country or "" }}</div>
                        {% endif %}
                    {% endif %}

                    {% set customer_ncc = frappe.db.get_value('Customer', doc.customer, 'tax_id') %}
                    {% if customer_ncc %}<div class="small"><strong>NCC :</strong> {{ customer_ncc }}</div>{% endif %}

                    {% set customer_regime = frappe.db.get_value('Customer', doc.customer, 'custom_regime_dimposition') %}
                    {% if customer_regime %}<div class="small"><strong>Régime d'imposition :</strong> {{ customer_regime }}</div>{% endif %}

                    {% set customer_rccm = frappe.db.get_value('Customer', doc.customer, 'custom_rccm') %}
                    {% if customer_rccm %}<div class="small"><strong>RCCM :</strong> {{ customer_rccm }}</div>{% endif %}
                </div>
            </div>
        </div>

        <!-- Objet + Période + Observation en flex -->
        {% if doc.title or doc.po_no or doc.custom_observation or doc.custom_pour_la_période_de %}
        <div class="row mb-10">
            <div class="col-xs-12">
                {% if doc.title or doc.po_no %}
                    <strong>Objet :</strong> <span style="text-transform: uppercase;">{{ doc.title or doc.name }}</span>
                    {% if doc.po_no %}
                        <br><strong>Réf. Client :</strong> {{ doc.po_no }}
                    {% endif %}
                {% endif %}

                <!-- Période -->
                {% if doc.custom_pour_la_période_de and doc.custom_pour_la_période_de|trim != "" %}
                <div style="margin-top: 8px; display: flex; gap: 8px; align-items: flex-start;">
                    <strong style="min-width: 80px;">Pour la période de :</strong>
                    <div style="word-break: break-word; flex: 1;">
                        {{ doc.custom_pour_la_période_de }}
                    </div>
                </div>
                {% endif %}

                <!-- Observation -->
                {% if doc.custom_observation and doc.custom_observation|trim != "" %}
                <div style="margin-top: 8px; display: flex; gap: 8px; align-items: flex-start;">
                    <strong style="min-width: 95px;">Observations :</strong>
                    <div style="word-break: break-word; flex: 1;">
                        {{ doc.custom_observation }}
                    </div>
                </div>
                {% endif %}
            </div>
        </div>
        {% endif %}

        <!-- Table des articles - Colonnes dynamiques -->
        <table class="table table-bordered table-condensed" style="margin-top: 5px;">
            <colgroup>
                <col style="width:4%">
                <col style="width:10%">
                <col style="width:25%">
                {% if has_discount %}<col style="width:6%">{% endif %}
                {% if has_discount %}<col style="width:9%">{% endif %}
                <col style="width:7%">
                {% if has_tva %}<col style="width:6%">{% endif %}
                <col style="width:12%">
                <col style="width:12%">
                <col style="width:14%">
            </colgroup>
            <thead>
                <tr>
                    <th class="text-center">N°</th>
                    <th class="text-center">Code</th>
                    <th class="text-center">Description</th>
                    {% if has_discount %}<th class="text-center">Remise %</th>{% endif %}
                    {% if has_discount %}<th class="text-right">Montant remise</th>{% endif %}
                    <th class="text-center">Qté</th>
                    {% if has_tva %}<th class="text-center">TVA</th>{% endif %}
                    <th class="text-right">P.U. HT</th>
                    <th class="text-right">Montant HT</th>
                    <th class="text-right">Montant TTC</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.items %}
                    {% set item_ht = item.amount or 0 %}
                    {% set item_tax = (doc.total_taxes_and_charges * (item_ht / doc.total)) if doc.total > 0 else 0 %}
                    {% set item_ttc = item_ht + item_tax %}

                    <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                        <td class="text-center">{{ loop.index }}</td>
                        <td class="text-center text-strong">{{ item.item_code }}</td>
                        <td>
                            <div class="text-strong">{{ item.item_name or item.item_code }}</div>
                            {% if item.description and item.description != item.item_name %}
                                <div class="desc">{{ item.description | replace("\n", "<br>") | safe }}</div>
                            {% endif %}
                        </td>
                        {% if has_discount %}
                        <td class="text-center small">
                            {% if item.discount_percentage and item.discount_percentage > 0 %}{{ item.discount_percentage|round(2) }}%{% else %}—{% endif %}
                        </td>
                        <td class="text-right small" style="color:#dc2626;">
                            {% if item.discount_percentage and item.discount_percentage > 0 and item.discount_amount and item.discount_amount > 0 %}- {{ fmt_amount(item.discount_amount, doc.currency) }}{% else %}—{% endif %}
                        </td>
                        {% endif %}
                        <td class="text-center">{{ item.qty|int }}</td>
                        {% if has_tva %}
                        <td class="text-center">{% if vat_rate and vat_rate > 0 %}{{ vat_rate }}%{% else %}—{% endif %}</td>
                        {% endif %}
                        <td class="text-right">{{ fmt_amount(item.rate, doc.currency) }}</td>
                        <td class="text-right">{{ fmt_amount(item_ht, doc.currency) }}</td>
                        <td class="text-right text-strong">{{ fmt_amount(item_ttc, doc.currency) }}</td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>

        <!-- Totaux -->
        <div class="row" style="margin-top:6px;">
            <div class="col-xs-6 col-xs-offset-6">
                <table style="width:100%; border:1.2px solid var(--accent);">
                    {% if doc.discount_amount and doc.discount_amount > 0 %}
                    <tr><td>Sous-total HT</td><td class="text-right">{{ fmt_amount(doc.net_total, doc.currency) }}</td></tr>
                    <tr><td>Remise globale{% if doc.additional_discount_percentage %} ({{ "{:.1f}".format(doc.additional_discount_percentage) }}%){% endif %}</td><td class="text-right">- {{ fmt_amount(doc.discount_amount, doc.currency) }}</td></tr>
                    {% endif %}
                    <tr><td>Total HT</td><td class="text-right">{{ fmt_amount(doc.total, doc.currency) }}</td></tr>
                    <tr><td>TVA{% if vat_rate and vat_rate > 0 %} {{ vat_rate }}%{% endif %}</td><td class="text-right">{{ fmt_amount(doc.total_taxes_and_charges, doc.currency) }}</td></tr>
                    <tr style="background:var(--accent); color:#fff;">
                        <td class="text-strong" style="color:#fff;">Total TTC</td>
                        <td class="text-right text-strong" style="color:#fff; font-size:11px;">{{ fmt_amount(doc.grand_total, doc.currency) }}</td>
                    </tr>
                    {% if doc.paid_amount and doc.paid_amount > 0 %}
                    <tr><td>Montant réglé</td><td class="text-right">{{ fmt_amount(doc.paid_amount, doc.currency) }}</td></tr>
                    {% endif %}
                    {% if doc.outstanding_amount is not none and doc.outstanding_amount > 0 %}
                    <tr><td>Reste à payer</td><td class="text-right" style="color:#dc2626;">{{ fmt_amount(doc.outstanding_amount, doc.currency) }}</td></tr>
                    {% endif %}
                </table>
            </div>
        </div>

        <!-- Montant en lettres -->
        <div class="small" style="font-style:italic; margin-top: 12px !important;">
            Arrêté à la somme de : 
            <strong style="text-transform: capitalize;">{{ montant_fr(doc.grand_total) }}</strong>
        </div>

        <!-- Échéancier de paiement -->
        {% if doc.payment_schedule and doc.payment_schedule|length > 0 %}
        <div style="margin-top:8px;">
            <div class="text-strong" style="font-size:9px; margin-bottom:2px;">Échéancier de paiement :</div>
            <table class="table table-bordered schedule-table">
                <thead>
                    <tr>
                        <th>Terme</th>
                        <th class="text-center">Date d'échéance</th>
                        <th class="text-center">Part (%)</th>
                        <th class="text-right">Montant</th>
                    </tr>
                </thead>
                <tbody>
                {% for ps in doc.payment_schedule %}
                    <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                        <td>{{ ps.payment_term or ps.description or "—" }}</td>
                        <td class="text-center">{{ frappe.utils.format_date(ps.due_date) if ps.due_date else "—" }}</td>
                        <td class="text-center">{{ "{:.2f}".format(ps.invoice_portion or 0) }}%</td>
                        <td class="text-right">{{ fmt_amount(ps.payment_amount, doc.currency) }}</td>
                    </tr>
                {% endfor %}
                </tbody>
            </table>
        </div>
        {% endif %}

        <!-- Termes et conditions -->
        {% if doc.terms and doc.terms|trim != "" %}
        <div class="terms-block">
            <span class="text-strong">Termes et Conditions :</span>
            <div style="white-space:pre-line; margin-top:3px;">{{ doc.terms }}</div>
        </div>
        {% endif %}

        <!-- FOOTER FIXE -->
        <div class="custom-footer">
            <div style="margin-bottom:2px;">
                <strong>S.A.R.L au capital de {{ capital_social }}</strong>
            </div>
            <div style="margin-bottom:2px;">
                {% if company.phone_no %}Tél : {{ company.phone_no }}{% endif %}
                {% if rccm %} &nbsp;|&nbsp; <strong>RCCM :</strong> {{ rccm }}{% endif %}
                {% if bank_info %} &nbsp;|&nbsp; <strong>{{ bank_info }}</strong>{% endif %}
            </div>
            {% if company.website %}
                <div><a href="{{ company.website }}">{{ company.website }}</a></div>
            {% endif %}
        </div>

    </div>
</div>
{% endfor %}

{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None) -%}
    {% if letter_head and not no_letterhead %}
        <div class="letter-head">{{ letter_head }}</div>
    {% endif %}
    {%- if doc.meta.is_submittable and doc.docstatus == 2 -%}
        <div class="text-center" document-status="cancelled">
            <h4 style="margin:0; color:#032A5F;">{{ _("ANNULÉ") }}</h4>
        </div>
    {%- endif -%}
{%- endmacro -%}

{# === Macro de formatage monétaire === #}
{%- macro fmt_amount(value, currency) -%}
    {%- set formatted = "{:,.2f}".format(value or 0).replace(",", " ").replace(".", ",") -%}
    {%- if currency == "XOF" -%}
        {{ formatted }} CFA
    {%- else -%}
        {{ formatted }} {{ currency or "" }}
    {%- endif -%}
{%- endmacro -%}

{# === Données société et adresses === #}
{% set company = frappe.get_cached_doc("Company", doc.company) %}
{% set logo_url = company.company_logo or frappe.db.get_value("Website Settings", None, "app_logo") %}
{% set buyer_full_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}

{% set billing_addr = frappe.db.get_value("Address", doc.billing_address, ["address_line1","address_line2","city","country","phone","email_id"], as_dict=True) if doc.billing_address else None %}
{% set supplier_addr = frappe.db.get_value("Address", doc.supplier_address, ["address_line1","address_line2","city","country","phone","email_id"], as_dict=True) if doc.supplier_address else None %}

{% set capital_social = company.get("custom_capital_social") or "1.000.000 F CFA" %}
{% set rccm = company.get("custom_rccm") or "CI ABJ6 03 2018 B12 33468" %}
{% set bank_info = company.get("custom_bank_account_display") or "Bank of Africa Côte d'Ivoire : CI032 01007 004065390013 37" %}
{% set company_address_line = company.get("custom_address_line") or "Cocody Riviera 3 villa 676, Abidjan — 11 BP 2624 ABJ 11" %}
{% set vat_rate = (doc.taxes[0].rate if doc.taxes and doc.taxes|length > 0 else 0) %}

{# === Détection remise et TVA pour masquer les colonnes === #}
{% set has_discount = false %}
{% set has_tva = false %}
{% for item in doc.items %}
    {% if item.discount_percentage and item.discount_percentage > 0 %}
        {% set has_discount = true %}
    {% endif %}
    {% if vat_rate and vat_rate > 0 %}
        {% set has_tva = true %}
    {% endif %}
{% endfor %}

{# === Macros nombre en lettres === #}
{%- macro _w1(n) -%}{%- if n|int==1 -%}un{%- elif n|int==2 -%}deux{%- elif n|int==3 -%}trois{%- elif n|int==4 -%}quatre{%- elif n|int==5 -%}cinq{%- elif n|int==6 -%}six{%- elif n|int==7 -%}sept{%- elif n|int==8 -%}huit{%- elif n|int==9 -%}neuf{%- endif -%}{%- endmacro -%}
{%- macro _w20(n) -%}{%- if n|int==0 -%}zéro{%- elif n|int==1 -%}un{%- elif n|int==2 -%}deux{%- elif n|int==3 -%}trois{%- elif n|int==4 -%}quatre{%- elif n|int==5 -%}cinq{%- elif n|int==6 -%}six{%- elif n|int==7 -%}sept{%- elif n|int==8 -%}huit{%- elif n|int==9 -%}neuf{%- elif n|int==10 -%}dix{%- elif n|int==11 -%}onze{%- elif n|int==12 -%}douze{%- elif n|int==13 -%}treize{%- elif n|int==14 -%}quatorze{%- elif n|int==15 -%}quinze{%- elif n|int==16 -%}seize{%- elif n|int==17 -%}dix-sept{%- elif n|int==18 -%}dix-huit{%- elif n|int==19 -%}dix-neuf{%- endif -%}{%- endmacro -%}
{%- macro _w100(n) -%}
{%- set n = n|int -%}
{%- if n < 20 -%}{{- _w20(n) -}}
{%- elif n < 30 -%}{%- if n == 20 -%}vingt{%- elif n == 21 -%}vingt et un{%- else -%}vingt-{{ _w1(n-20) }}{%- endif -%}
{%- elif n < 40 -%}{%- if n == 30 -%}trente{%- elif n == 31 -%}trente et un{%- else -%}trente-{{ _w1(n-30) }}{%- endif -%}
{%- elif n < 50 -%}{%- if n == 40 -%}quarante{%- elif n == 41 -%}quarante et un{%- else -%}quarante-{{ _w1(n-40) }}{%- endif -%}
{%- elif n < 60 -%}{%- if n == 50 -%}cinquante{%- elif n == 51 -%}cinquante et un{%- else -%}cinquante-{{ _w1(n-50) }}{%- endif -%}
{%- elif n < 70 -%}{%- if n == 60 -%}soixante{%- elif n == 61 -%}soixante et un{%- else -%}soixante-{{ _w1(n-60) }}{%- endif -%}
{%- elif n < 80 -%}{%- if n == 70 -%}soixante-dix{%- elif n == 71 -%}soixante et onze{%- else -%}soixante-{{ _w20(n-60) }}{%- endif -%}
{%- elif n < 90 -%}{%- if n == 80 -%}quatre-vingts{%- else -%}quatre-vingt-{{ _w1(n-80) }}{%- endif -%}
{%- else -%}{%- if n == 90 -%}quatre-vingt-dix{%- else -%}quatre-vingt-{{ _w20(n-80) }}{%- endif -%}
{%- endif -%}
{%- endmacro -%}
{%- macro _w1000(n) -%}
{%- set n = n|int -%}
{%- set h = n // 100 -%}
{%- set r = n % 100 -%}
{%- if h > 0 -%}
    {%- if h == 1 -%}cent{%- if r > 0 %} {{ _w100(r) }}{%- endif -%}
    {%- else -%}{{ _w1(h) }} cent{%- if r > 0 %} {{ _w100(r) }}{%- else %}s{%- endif -%}
    {%- endif -%}
{%- else -%}{{ _w100(r) }}{%- endif -%}
{%- endmacro -%}
{%- macro montant_fr(amount) -%}
{%- set n = (amount or 0)|round(0)|int -%}
{%- if n == 0 -%}
    zéro franc CFA
{%- else -%}
    {%- set milliards = n // 1000000000 -%}
    {%- set reste1 = n % 1000000000 -%}
    {%- set millions = reste1 // 1000000 -%}
    {%- set reste2 = reste1 % 1000000 -%}
    {%- set mille = reste2 // 1000 -%}
    {%- set reste = reste2 % 1000 -%}
    {%- set p1 = (_w1000(milliards) ~ " milliards") if milliards > 1 else ("un milliard" if milliards == 1 else "") -%}
    {%- set p2 = (_w1000(millions) ~ " millions") if millions > 1 else ("un million" if millions == 1 else "") -%}
    {%- set p3 = (_w1000(mille) ~ " mille") if mille > 1 else ("mille" if mille == 1 else "") -%}
    {%- set p4 = _w1000(reste) if reste > 0 else "" -%}
    {%- set text = "" -%}
    {%- if p1 %}{%- set text = text ~ p1 ~ " " %}{%- endif -%}
    {%- if p2 %}{%- set text = text ~ p2 ~ " " %}{%- endif -%}
    {%- if p3 %}{%- set text = text ~ p3 ~ " " %}{%- endif -%}
    {%- if p4 %}{%- set text = text ~ p4 ~ " " %}{%- endif -%}
    {{- text | trim }} franc{%- if n > 1 -%}s{%- endif -%}
{%- endif -%}
{%- endmacro -%}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&display=swap');
    :root { --primary: #032A5F; --accent: #0756C5; }
    @page { size: A4; margin: 8mm 8mm 50mm 8mm; }
    .print-format {
        padding: 0 20px 90px 20px !important;
        font-size: 10.5px;
        line-height: 1.25;
        font-family: 'Montserrat', Arial, Helvetica, sans-serif;
        color: var(--primary);
    }
    label { color: var(--accent); font-size: 9.5px; margin-bottom: 2px; font-weight: 600; }
    .text-strong { font-weight: 700; color: var(--primary); }
    .small { font-size: 9.5px; color: var(--primary); }
    .desc { font-size: 9.5px; color: var(--primary); }
    h2.text-strong { margin: 0 !important; font-size: 13px; text-transform: uppercase; }

    table { width:100%; border-collapse: collapse; }
    .table-bordered { border: 1.5px solid var(--accent); }
    .table>thead>tr>th, .table>tbody>tr>td { vertical-align: top; padding: 3px 5px; line-height: 1.2; color: var(--primary); }
    .table>thead>tr>th { background-color: var(--accent); color: #fff; font-weight: 600; }

    .box { border: 1.5px solid var(--accent); padding: 5px 7px; border-radius: 5px; background-color: #f8fbff; }
    .logo-cell { width: 180px; height: 90px; }
    .row-alt { background-color: #f8fbff; }

    .signature-box {
        position: fixed; bottom: 32mm; right: 8mm; width: 45%;
        border: 1.5px solid var(--accent); border-radius: 4px;
        padding: 4px 10px 5px 10px; background-color: #f8fbff; z-index: 10;
    }
    .signature-box .signature-title {
        font-weight: 700; color: var(--accent); font-size: 9px;
        text-transform: uppercase; letter-spacing: 0.4px;
        border-bottom: 1px solid var(--accent); padding-bottom: 2px;
        margin-bottom: 4px; text-align: center;
    }
    .signature-space { height: 18px; border-bottom: 1px dashed var(--primary); margin-top: 3px; }

    .custom-footer {
        position: fixed; bottom: 0; left: 0; right: 0;
        color: #032A5F; font-size: 9px;
        border-top: 1px solid #032A5F;
        padding: 5px 8mm 3px 8mm; text-align: center; line-height: 1.35;
        background: #fff;
    }
    .custom-footer a { color: #032A5F; text-decoration: none; font-weight: 600; }

    .schedule-table th { background-color: #e8f0fb; color: var(--primary); font-weight: 600; font-size: 9px; }
    .schedule-table td { font-size: 9px; padding: 2px 4px !important; }
    .terms-block { font-size: 8.5px; line-height: 1.3; color: var(--primary); border-top: 1px solid var(--accent); padding-top: 3px; margin-top: 3px; }
</style>

{% for page in layout %}
<div class="page-break">
    <div class="print-format">

        <!-- Titre -->
        <div class="row text-center">
            <h2 class="text-strong" style="margin:0; text-transform:uppercase;">{{ _("Facture d'Achat") }}</h2>
        </div>

        <!-- Logo -->
        <div class="row mb-4">
            <div class="col-xs-6 logo-cell">
                {% if logo_url %}<img src="{{ logo_url }}" alt="logo" style="max-width:100%; max-height:100%;">{% endif %}
            </div>
        </div>

        <!-- En-tête infos -->
        <div class="row mb-10">
            <div class="col-xs-8">
                <div><span class="text-strong">Devise :</span> {{ "Franc CFA" if doc.currency == "XOF" else (doc.currency or "") }}</div>
                <div><span class="text-strong">Date d'émission :</span> {{ frappe.utils.format_date(doc.posting_date) }}</div>
                <div class="small"><span class="text-strong">Date d'impression :</span> {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm:ss") }}</div>

                {% if doc.contact_display or doc.contact_email or doc.contact_mobile %}
                <div style="margin-top: 6px;">
                    <div class="text-strong" style="margin-bottom:2px;">Contact Fournisseur :</div>
                    {% if doc.contact_display %}<div class="small">{{ doc.contact_display }}</div>{% endif %}
                    {% if doc.contact_email %}<div class="small">{{ doc.contact_email }}</div>{% endif %}
                    {% if doc.contact_mobile %}<div class="small">{{ doc.contact_mobile }}</div>{% endif %}
                </div>
                {% endif %}
            </div>

            <div class="col-xs-4">
                <div class="mb-10"><span class="text-strong">N° de facture :</span> {{ doc.name }}</div>
                <div class="mb-10"><span class="text-strong">Date de facture :</span> {{ frappe.utils.format_date(doc.posting_date) }}</div>
                {% if doc.bill_no %}
                    <div class="mb-10"><span class="text-strong">N° facture fournisseur :</span> {{ doc.bill_no }}</div>
                {% endif %}
                {% if doc.bill_date %}
                    <div class="mb-10"><span class="text-strong">Date facture fournisseur :</span> {{ frappe.utils.format_date(doc.bill_date) }}</div>
                {% endif %}
                <div class="mb-10"><span class="text-strong">Date d'échéance :</span> {{ frappe.utils.format_date(doc.due_date) if doc.due_date else "—" }}</div>
            </div>
        </div>

        <!-- Adresses -->
        <div class="row mb-10">
            <!-- Adresse du fournisseur (à gauche) -->
            <div class="col-xs-6">
                <div class="box">
                    <div class="text-strong" style="margin-bottom:3px;">Adresse du fournisseur :</div>
                    <div class="small"><strong>Nom :</strong> {{ doc.supplier_name or doc.supplier or "" }}</div>
                    {% if supplier_addr %}
                        {% if supplier_addr.address_line1 or supplier_addr.address_line2 %}
                            <div class="small"><strong>Adresse :</strong> {{ supplier_addr.address_line1 or "" }} {{ supplier_addr.address_line2 or "" }}</div>
                        {% endif %}
                        {% if supplier_addr.city or supplier_addr.country %}
                            <div class="small"><strong>Ville / Pays :</strong> {{ supplier_addr.city or "" }} {{ supplier_addr.country or "" }}</div>
                        {% endif %}
                        {% if supplier_addr.phone %}<div class="small"><strong>Téléphone :</strong> {{ supplier_addr.phone }}</div>{% endif %}
                        {% if supplier_addr.email_id %}<div class="small"><strong>Email :</strong> {{ supplier_addr.email_id }}</div>{% endif %}
                    {% endif %}
                    {% set supplier_ncc = frappe.db.get_value('Supplier', doc.supplier, 'tax_id') %}
                    {% if supplier_ncc %}<div class="small"><strong>NCC :</strong> {{ supplier_ncc }}</div>{% endif %}
                    {% set supplier_regime = frappe.db.get_value('Supplier', doc.supplier, 'custom_regime_dimposition') %}
                    {% if supplier_regime %}<div class="small"><strong>Régime d'imposition :</strong> {{ supplier_regime }}</div>{% endif %}
                    {% set supplier_rccm = frappe.db.get_value('Supplier', doc.supplier, 'custom_rccm') %}
                    {% if supplier_rccm %}<div class="small"><strong>RCCM :</strong> {{ supplier_rccm }}</div>{% endif %}
                </div>
            </div>

            <!-- Adresse de facturation et livraison (à droite) -->
            <div class="col-xs-6">
                <div class="box">
                    <div class="text-strong" style="margin-bottom:3px;">Adresse de facturation et de livraison :</div>
                    <div class="small"><strong>Nom :</strong> {{ company.company_name }}</div>
                    {% if billing_addr %}
                        {% if billing_addr.address_line1 or billing_addr.address_line2 %}
                            <div class="small"><strong>Adresse :</strong> {{ billing_addr.address_line1 or "" }} {{ billing_addr.address_line2 or "" }}</div>
                        {% endif %}
                        {% if billing_addr.city or billing_addr.country %}
                            <div class="small"><strong>Ville / Pays :</strong> {{ billing_addr.city or "" }} {{ billing_addr.country or "" }}</div>
                        {% endif %}
                    {% endif %}
                    {% if company.tax_id %}<div class="small"><strong>NCC :</strong> {{ company.tax_id }}</div>{% endif %}
                    {% if company.custom_regime_dimposition %}<div class="small"><strong>Régime d'imposition :</strong> {{ company.custom_regime_dimposition }}</div>{% endif %}
                    {% if company.custom_rccm or rccm %}<div class="small"><strong>RCCM :</strong> {{ company.custom_rccm or rccm }}</div>{% endif %}
                </div>
            </div>
        </div>

        <!-- Observation en flex -->
        {% if doc.custom_observation and doc.custom_observation|trim != "" %}
        <div class="row mb-10">
            <div class="col-xs-12">
                <div style="display: flex; gap: 10px; align-items: flex-start;">
                    <strong style="min-width: 110px;">Observations :</strong>
                    <div style="white-space: pre-line; word-break: break-word; flex: 1;">
                        {{ doc.custom_observation }}
                    </div>
                </div>
            </div>
        </div>
        {% endif %}

        <!-- Table des articles - Colonnes dynamiques -->
        <table class="table table-bordered table-condensed mb-0" style="font-size:10.5px;">
            <colgroup>
                <col style="width:5%">
                <col style="width:12%">
                <col style="width:28%">
                {% if has_discount %}<col style="width:7%">{% endif %}
                {% if has_discount %}<col style="width:9%">{% endif %}
                <col style="width:7%">
                <col style="width:6%">
                {% if has_tva %}<col style="width:6%">{% endif %}
                <col style="width:12%">
                <col style="width:13%">
            </colgroup>
            <thead>
                <tr>
                    <th class="text-center">N°</th>
                    <th class="text-center">Code article</th>
                    <th class="text-center">Description</th>
                    {% if has_discount %}<th class="text-center">Remise %</th>{% endif %}
                    {% if has_discount %}<th class="text-right">Montant remise</th>{% endif %}
                    <th class="text-center">Qté</th>
                    <th class="text-center">UdM</th>
                    {% if has_tva %}<th class="text-center">TVA</th>{% endif %}
                    <th class="text-right">Prix unit. HT</th>
                    <th class="text-right">Montant HT</th>
                </tr>
            </thead>
            <tbody>
            {% for item in doc.items %}
                <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                    <td class="text-center">{{ loop.index }}</td>
                    <td class="text-center text-strong">{{ item.item_code }}</td>
                    <td>
                        <div class="text-strong">{{ item.item_name }}</div>
                        {% if item.description and (item.description != item.item_name) %}
                            <div class="desc">{{ item.description }}</div>
                        {% endif %}
                    </td>
                    {% if has_discount %}
                    <td class="text-center small">
                        {% if item.discount_percentage and item.discount_percentage > 0 %}{{ item.discount_percentage|round(2) }}%{% else %}—{% endif %}
                    </td>
                    <td class="text-right small" style="color:#dc2626;">
                        {% if item.discount_percentage and item.discount_percentage > 0 and item.discount_amount and item.discount_amount > 0 %}- {{ fmt_amount(item.discount_amount, doc.currency) }}{% else %}—{% endif %}
                    </td>
                    {% endif %}
                    <td class="text-center">{{ item.get_formatted("qty", 0) }}</td>
                    <td class="text-center">{{ item.uom }}</td>
                    {% if has_tva %}
                    <td class="text-center">{% if vat_rate and vat_rate > 0 %}{{ vat_rate|int }}%{% else %}—{% endif %}</td>
                    {% endif %}
                    <td class="text-right">{{ fmt_amount(item.rate, doc.currency) }}</td>
                    <td class="text-right text-strong">{{ fmt_amount(item.amount, doc.currency) }}</td>
                </tr>
            {% endfor %}
            </tbody>
        </table>

        <!-- Totaux -->
        <div class="row" style="margin-top:5px;">
            <div class="col-xs-6 col-xs-offset-6">
                <div class="row" style="padding: 3px 0; border-bottom: 1px solid var(--accent);">
                    <div class="col-xs-6">Total Net HT</div>
                    <div class="col-xs-6 text-right">{{ fmt_amount(doc.total, doc.currency) }}</div>
                </div>
                {% if doc.discount_amount and doc.discount_amount > 0 %}
                <div class="row" style="padding: 2px 0; border-bottom: 1px solid var(--accent);">
                    <div class="col-xs-6 desc">Remise{% if doc.additional_discount_percentage %} ({{ "{:.2f}".format(doc.additional_discount_percentage) }}%){% endif %}</div>
                    <div class="col-xs-6 text-right desc">- {{ fmt_amount(doc.discount_amount, doc.currency) }}</div>
                </div>
                <div class="row" style="padding: 2px 0; border-bottom: 1px solid var(--accent);">
                    <div class="col-xs-6">Total après remise</div>
                    <div class="col-xs-6 text-right">{{ fmt_amount(doc.net_total, doc.currency) }}</div>
                </div>
                {% endif %}
                {% if doc.taxes %}
                    {% for tax in doc.taxes %}
                        {% if tax.tax_amount %}
                        <div class="row tax-line">
                            <div class="col-xs-7 desc">{{ tax.description or tax.account_head }}</div>
                            <div class="col-xs-5 text-right desc">{{ fmt_amount(tax.tax_amount, doc.currency) }}</div>
                        </div>
                        {% endif %}
                    {% endfor %}
                {% endif %}
                <div class="row" style="padding: 2px 0; border-bottom: 1px solid var(--accent);">
                    <div class="col-xs-6">Total Taxes et Frais</div>
                    <div class="col-xs-6 text-right">{{ fmt_amount(doc.base_total_taxes_and_charges, doc.currency) }}</div>
                </div>
                <div class="row" style="padding: 4px 0; background-color: var(--accent); color:#fff; border-radius: 4px; margin-top: 3px;">
                    <div class="col-xs-6"><span class="text-strong" style="color:#fff;">Total TTC</span></div>
                    <div class="col-xs-6 text-right text-strong" style="color:#fff;">{{ fmt_amount(doc.grand_total, doc.currency) }}</div>
                </div>
                {% if doc.outstanding_amount is defined %}
                <div class="row" style="padding: 2px 0; border-bottom: 1px solid var(--accent);">
                    <div class="col-xs-6">Montant payé</div>
                    <div class="col-xs-6 text-right">{{ fmt_amount((doc.grand_total or 0) - (doc.outstanding_amount or 0), doc.currency) }}</div>
                </div>
                <div class="row" style="padding: 2px 0;">
                    <div class="col-xs-6 text-strong">Solde dû</div>
                    <div class="col-xs-6 text-right text-strong">{{ fmt_amount(doc.outstanding_amount, doc.currency) }}</div>
                </div>
                {% endif %}
            </div>
        </div>

        <!-- Montant en lettres -->
        <div class="small" style="font-style:italic; margin-top:4px;">
            Arrêté à la somme de : <strong style="text-transform: capitalize;">{{ montant_fr(doc.grand_total) }}</strong>
        </div>

        <!-- Échéancier de paiement -->
        {% if doc.payment_schedule and doc.payment_schedule|length >= 1 %}
        <div style="margin-top:5px;">
            <div class="text-strong" style="margin-bottom:2px; font-size:9px;">Échéancier de paiement :</div>
            <table class="table table-bordered schedule-table">
                <thead>
                    <tr>
                        <th>Terme</th>
                        <th class="text-center">Date d'échéance</th>
                        <th class="text-center">Part (%)</th>
                        <th class="text-right">Montant</th>
                    </tr>
                </thead>
                <tbody>
                {% for ps in doc.payment_schedule %}
                    <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                        <td>{{ ps.payment_term or ps.description or "—" }}</td>
                        <td class="text-center">{{ frappe.utils.format_date(ps.due_date) if ps.due_date else "—" }}</td>
                        <td class="text-center">{{ "{:.2f}".format(ps.invoice_portion or 0) }}%</td>
                        <td class="text-right text-strong">{{ fmt_amount(ps.payment_amount, doc.currency) }}</td>
                    </tr>
                {% endfor %}
                </tbody>
            </table>
        </div>
        {% endif %}

        <!-- Termes et conditions -->
        {% if doc.terms and doc.terms|trim != "" %}
        <div class="terms-block">
            <span class="text-strong">Termes et Conditions :</span>
            <div style="white-space: pre-line; word-break: break-word; margin-top: 2px;">{{ doc.terms }}</div>
        </div>
        {% endif %}

        <!-- FOOTER FIXE -->
        <div class="custom-footer">
            <div style="margin-bottom:2px;">
                <strong>S.A.R.L au capital de {{ capital_social }}</strong>
                {% if company_address_line %} — {{ company_address_line }}{% endif %}
            </div>
            <div style="margin-bottom:2px;">
                {% if company.phone_no %}Tél : {{ company.phone_no }}{% endif %}
                {% if rccm %} &nbsp;|&nbsp; <strong>RCCM :</strong> {{ rccm }}{% endif %}
                {% if bank_info %} &nbsp;|&nbsp; <strong>{{ bank_info }}</strong>{% endif %}
            </div>
            {% if company.website %}
                <div><a href="{{ company.website }}">{{ company.website }}</a></div>
            {% endif %}
        </div>

    </div>
</div>
{% endfor %}

{# === Formatage monétaire === #}
{%- macro fmt_amount(value, currency) -%}
    {%- set formatted = "{:,.2f}".format(value or 0).replace(",", " ").replace(".", ",") -%}
    {%- if currency in ["XOF", "CFA", "FCFA"] -%}
        {{ formatted }} CFA
    {%- else -%}
        {{ formatted }} {{ currency or "" }}
    {%- endif -%}
{%- endmacro -%}

{# === Macros nombre en lettres === #}
{%- macro _w1(n) -%}{%- if n|int==1 -%}un{%- elif n|int==2 -%}deux{%- elif n|int==3 -%}trois{%- elif n|int==4 -%}quatre{%- elif n|int==5 -%}cinq{%- elif n|int==6 -%}six{%- elif n|int==7 -%}sept{%- elif n|int==8 -%}huit{%- elif n|int==9 -%}neuf{%- endif -%}{%- endmacro -%}
{%- macro _w20(n) -%}{%- if n|int==0 -%}zéro{%- elif n|int==1 -%}un{%- elif n|int==2 -%}deux{%- elif n|int==3 -%}trois{%- elif n|int==4 -%}quatre{%- elif n|int==5 -%}cinq{%- elif n|int==6 -%}six{%- elif n|int==7 -%}sept{%- elif n|int==8 -%}huit{%- elif n|int==9 -%}neuf{%- elif n|int==10 -%}dix{%- elif n|int==11 -%}onze{%- elif n|int==12 -%}douze{%- elif n|int==13 -%}treize{%- elif n|int==14 -%}quatorze{%- elif n|int==15 -%}quinze{%- elif n|int==16 -%}seize{%- elif n|int==17 -%}dix-sept{%- elif n|int==18 -%}dix-huit{%- elif n|int==19 -%}dix-neuf{%- endif -%}{%- endmacro -%}
{%- macro _w100(n) -%}
{%- set n = n|int -%}
{%- if n < 20 -%}{{- _w20(n) -}}
{%- elif n < 30 -%}{%- if n == 20 -%}vingt{%- elif n == 21 -%}vingt et un{%- else -%}vingt-{{ _w1(n-20) }}{%- endif -%}
{%- elif n < 40 -%}{%- if n == 30 -%}trente{%- elif n == 31 -%}trente et un{%- else -%}trente-{{ _w1(n-30) }}{%- endif -%}
{%- elif n < 50 -%}{%- if n == 40 -%}quarante{%- elif n == 41 -%}quarante et un{%- else -%}quarante-{{ _w1(n-40) }}{%- endif -%}
{%- elif n < 60 -%}{%- if n == 50 -%}cinquante{%- elif n == 51 -%}cinquante et un{%- else -%}cinquante-{{ _w1(n-50) }}{%- endif -%}
{%- elif n < 70 -%}{%- if n == 60 -%}soixante{%- elif n == 61 -%}soixante et un{%- else -%}soixante-{{ _w1(n-60) }}{%- endif -%}
{%- elif n < 80 -%}{%- if n == 70 -%}soixante-dix{%- elif n == 71 -%}soixante et onze{%- else -%}soixante-{{ _w20(n-60) }}{%- endif -%}
{%- elif n < 90 -%}{%- if n == 80 -%}quatre-vingts{%- else -%}quatre-vingt-{{ _w1(n-80) }}{%- endif -%}
{%- else -%}{%- if n == 90 -%}quatre-vingt-dix{%- else -%}quatre-vingt-{{ _w20(n-80) }}{%- endif -%}
{%- endif -%}
{%- endmacro -%}

{%- macro _w1000(n) -%}
{%- set n = n|int -%}
{%- set h = n // 100 -%}
{%- set r = n % 100 -%}
{%- if h > 0 -%}
    {%- if h == 1 -%}cent{%- if r > 0 %} {{ _w100(r) }}{%- endif -%}
    {%- else -%}{{ _w1(h) }} cent{%- if r > 0 %} {{ _w100(r) }}{%- else %}s{%- endif -%}
    {%- endif -%}
{%- else -%}{{ _w100(r) }}{%- endif -%}
{%- endmacro -%}

{%- macro montant_fr(amount) -%}
{%- set n = (amount or 0)|round(0)|int -%}
{%- if n == 0 -%}
    zéro franc CFA
{%- else -%}
    {%- set milliards = n // 1000000000 -%}
    {%- set reste1 = n % 1000000000 -%}
    {%- set millions = reste1 // 1000000 -%}
    {%- set reste2 = reste1 % 1000000 -%}
    {%- set mille = reste2 // 1000 -%}
    {%- set reste = reste2 % 1000 -%}
    {%- set p1 = (_w1000(milliards) ~ " milliards") if milliards > 1 else ("un milliard" if milliards == 1 else "") -%}
    {%- set p2 = (_w1000(millions) ~ " millions") if millions > 1 else ("un million" if millions == 1 else "") -%}
    {%- set p3 = (_w1000(mille) ~ " mille") if mille > 1 else ("mille" if mille == 1 else "") -%}
    {%- set p4 = _w1000(reste) if reste > 0 else "" -%}
    {%- set text = "" -%}
    {%- if p1 %}{%- set text = text ~ p1 ~ " " %}{%- endif -%}
    {%- if p2 %}{%- set text = text ~ p2 ~ " " %}{%- endif -%}
    {%- if p3 %}{%- set text = text ~ p3 ~ " " %}{%- endif -%}
    {%- if p4 %}{%- set text = text ~ p4 ~ " " %}{%- endif -%}
    {{- text | trim }} franc{%- if n > 1 -%}s{%- endif -%}
{%- endif -%}
{%- endmacro -%}

{# === Données société === #}
{% set company = frappe.get_cached_doc("Company", doc.company) %}
{% set logo_url = company.company_logo or frappe.db.get_value("Website Settings", None, "app_logo") %}
{% set owner_fullname = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}

{% set co_addr_display = company.custom_adresse or company.custom_address_line or "Cocody Riviera 3 villa 676, Abidjan — 11 BP 2624 ABJ 11" %}
{% set capital_social = company.get("custom_capital_social") or "1.000.000 F CFA" %}
{% set rccm = company.get("custom_rccm") or company.custom_numéro_rccm or "CI-ABJ6-03-2018-B12-33468" %}
{% set bank_info = company.get("custom_bank_account_display") or "Bank of Africa Côte d'Ivoire : CI032 01007 004065390013 37" %}

{# === Données client (party) === #}
{% set customer_name_display = frappe.db.get_value("Customer", doc.party, "customer_name") if doc.party_type == "Customer" else doc.party %}
{% set customer_address_name = frappe.db.get_value("Dynamic Link",
    {"link_doctype": doc.party_type, "link_name": doc.party, "parenttype": "Address"},
    "parent") %}
{% set billing_addr = frappe.db.get_value("Address", customer_address_name,
    ["address_line1","address_line2","city","country","phone","email_id"], as_dict=True)
    if customer_address_name else None %}

{# === Intervalle de facturation en français === #}
{%- set interval_map = {"Day": "Jour(s)", "Week": "Semaine(s)", "Month": "Mois", "Year": "An(s)"} -%}
{%- set billing_label = interval_map.get(doc.billing_interval, doc.billing_interval or "") -%}
{%- set billing_freq = ((doc.billing_interval_count|string ~ " ") if doc.billing_interval_count and doc.billing_interval_count > 1 else "") ~ billing_label -%}

{# === Statut couleur === #}
{%- set status_colors = {
    "Active": "#16a34a",
    "Past Due Date": "#d97706",
    "Cancelled": "#dc2626",
    "Completed": "#2563eb",
    "Trialling": "#7c3aed"
} -%}
{%- set status_labels = {
    "Active": "Actif",
    "Past Due Date": "En retard",
    "Cancelled": "Annulé",
    "Completed": "Terminé",
    "Trialling": "Période d'essai"
} -%}
{%- set status_color = status_colors.get(doc.status, "#6b7280") -%}
{%- set status_label = status_labels.get(doc.status, doc.status or "") -%}

{# === Labels generate_invoice_at === #}
{%- set invoice_at_labels = {
    "Start of the current subscription period": "Début de période",
    "End of the current subscription period": "Fin de période",
    "Days before the period start date": "Jours avant début",
    "Days after the period start date": "Jours après début"
} -%}

{# === Calcul des totaux depuis les plans === #}
{%- set total_ht = namespace(value=0) -%}
{%- for plan in doc.plans -%}
    {%- set plan_cost = frappe.db.get_value('Subscription Plan', plan.plan, 'cost') or 0 -%}
    {%- set total_ht.value = total_ht.value + (plan_cost * (plan.qty or 1)) -%}
{%- endfor -%}

{# === Calcul remise === #}
{%- set remise_pct = (doc.additional_discount_percentage or 0) -%}
{%- set remise_fixe = (doc.additional_discount_amount or 0) -%}
{%- set remise_montant = namespace(value=0) -%}
{%- if doc.apply_additional_discount and (remise_pct > 0 or remise_fixe > 0) -%}
    {%- if remise_pct > 0 -%}
        {%- set remise_montant.value = total_ht.value * remise_pct / 100 -%}
    {%- else -%}
        {%- set remise_montant.value = remise_fixe -%}
    {%- endif -%}
{%- endif -%}
{%- set total_net = total_ht.value - remise_montant.value -%}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&display=swap');
    :root { --primary: #032A5F; --accent: #0756C5; }
    @page { size: A4; margin: 5mm 5mm 38mm 5mm; }

    .print-format {
        padding: 0 12px 60px 12px !important;
        font-size: 9.8px;
        line-height: 1.18;
        font-family: 'Montserrat', Arial, Helvetica, sans-serif;
        color: var(--primary);
    }

    label { color: var(--accent); font-size: 9px; margin-bottom: 1px; font-weight: 600; }
    .text-strong { font-weight: 700; color: var(--primary); }
    .small { font-size: 8.8px; color: var(--primary); }
    .desc { font-size: 8.8px; color: var(--primary); }

    h2.text-strong {
        margin: 0 !important;
        font-size: 12.5px;
        text-transform: uppercase;
        letter-spacing: 0.4px;
    }

    table { width:100%; border-collapse: collapse; }
    .table-bordered { border: 1.2px solid var(--accent); }
    .table>thead>tr>th, .table>tbody>tr>td {
        padding: 2px 4px;
        line-height: 1.15;
        vertical-align: top;
    }
    .table>thead>tr>th {
        background-color: var(--accent);
        color: #fff;
        font-weight: 600;
        padding: 3px 4px;
    }

    .box {
        border: 1.2px solid var(--accent);
        padding: 4px 6px;
        border-radius: 5px;
        background-color: #f8fbff;
    }

    .row-alt { background-color: #f8fbff; }
    .logo-cell { width: 180px; height: 90px; }

    .status-badge {
        display: inline-block;
        padding: 2px 8px;
        border-radius: 10px;
        font-size: 8.5px;
        font-weight: 700;
        letter-spacing: 0.3px;
        text-transform: uppercase;
    }

    .plan-meta {
        font-size: 8px;
        color: var(--accent);
        margin-top: 2px;
        line-height: 1.3;
    }
    .plan-meta span { margin-right: 6px; }

    .tag {
        display: inline-block;
        background: #e8f0fb;
        border-radius: 3px;
        padding: 1px 4px;
        font-size: 7.8px;
        color: var(--primary);
        font-weight: 600;
        margin-right: 3px;
        margin-bottom: 1px;
    }

    .signature-box {
        position: fixed; bottom: 26mm; right: 5mm; width: 48%;
        border: 1.2px solid var(--accent); border-radius: 3px;
        padding: 3px 8px 4px; background-color: #f8fbff; z-index: 10;
    }
    .signature-box .signature-title {
        font-weight: 700; color: var(--accent); font-size: 8.5px;
        text-transform: uppercase; letter-spacing: 0.3px;
        border-bottom: 1px solid var(--accent); padding-bottom: 2px;
        margin-bottom: 3px; text-align: center;
    }
    .signature-space { height: 15px; border-bottom: 1px dashed var(--primary); margin-top: 2px; }

    .custom-footer {
        position: fixed; bottom: 0; left: 0; right: 0;
        color: var(--primary); font-size: 8.5px;
        border-top: 1.2px solid var(--accent);
        padding: 4px 6mm 3px 6mm; text-align: center; line-height: 1.3;
        background: #fff;
    }

    .terms-block { font-size: 8.5px; line-height: 1.25; margin-top: 5px; }
    .schedule-table th {
        background-color: #e8f0fb;
        color: var(--primary);
        font-weight: 600;
        font-size: 8.5px;
    }
    .schedule-table td {
        font-size: 8.5px;
        padding: 2px 4px !important;
    }
    .totaux-table td { padding: 2px 4px !important; font-size: 9px; }
    .section-title {
        font-size: 8.5px;
        font-weight: 700;
        color: var(--accent);
        text-transform: uppercase;
        letter-spacing: 0.3px;
        border-bottom: 1px solid var(--accent);
        padding-bottom: 2px;
        margin-bottom: 4px;
        margin-top: 6px;
    }
</style>

{% for page in layout %}
<div class="page-break">
    <div class="print-format">

        <!-- Titre + Statut -->
        <div class="row text-center" style="position: relative;">
            <h2 class="text-strong">{{ _("Contrat d'Abonnement") }}</h2>
            <div style="position: absolute; right: 0; top: 0;">
                <span class="status-badge" style="background-color: {{ status_color }}; color: #fff;">
                    {{ status_label }}
                </span>
            </div>
        </div>

        <!-- Logo -->
        <div class="row mb-10">
            <div class="col-xs-6 logo-cell">
                {% if logo_url %}
                    <img src="{{ logo_url }}" alt="logo" style="max-width:100%; max-height:100%;">
                {% endif %}
            </div>
        </div>

        <!-- En-tête infos société -->
        <div class="row mb-10">
            <div class="col-xs-7">
                <div><span class="text-strong">Société :</span> {{ company.company_name }}</div>
                <div><span class="text-strong">Adresse :</span> {{ co_addr_display }}</div>
                {% if company.tax_id %}<div><span class="text-strong">NCC :</span> {{ company.tax_id }}</div>{% endif %}
                {% if company.custom_regime_dimposition %}<div><span class="text-strong">Régime d'imposition :</span> {{ company.custom_regime_dimposition }}</div>{% endif %}
                <div><span class="text-strong">RCCM :</span> {{ rccm }}</div>
                <div class="small"><span class="text-strong">Interlocuteur :</span> {{ owner_fullname }}</div>
            </div>

            <div class="col-xs-5">
                <div class="mb-10">
                    <div><span class="text-strong">N° Abonnement :</span> {{ doc.name }}</div>
                </div>
                {% if doc.start_date %}
                <div class="mb-10">
                    <div><span class="text-strong">Date de début :</span> {{ frappe.utils.format_date(doc.start_date, "dd MMMM yyyy") }}</div>
                </div>
                {% endif %}
                {% if doc.end_date %}
                <div class="mb-10">
                    <div><span class="text-strong">Date de fin :</span> {{ frappe.utils.format_date(doc.end_date, "dd MMMM yyyy") }}</div>
                </div>
                {% endif %}
                {% if doc.cancelation_date %}
                <div class="mb-10">
                    <div><span class="text-strong">Date d'annulation :</span> {{ frappe.utils.format_date(doc.cancelation_date, "dd MMMM yyyy") }}</div>
                </div>
                {% endif %}
                {% if billing_freq %}
                <div class="mb-10">
                    <div><span class="text-strong">Périodicité :</span> {{ billing_freq }}</div>
                </div>
                {% endif %}
                {% if doc.generate_invoice_at %}
                <div class="mb-10">
                    <div><span class="text-strong">Génération facture :</span> {{ invoice_at_labels.get(doc.generate_invoice_at, doc.generate_invoice_at) }}</div>
                </div>
                {% endif %}
                {% if doc.number_of_days %}
                <div class="mb-10">
                    <div><span class="text-strong">Nombre de jours :</span> {{ doc.number_of_days }}</div>
                </div>
                {% endif %}
                {% if doc.days_until_due %}
                <div class="mb-10">
                    <div><span class="text-strong">Délai de paiement :</span> {{ doc.days_until_due }} jour(s)</div>
                </div>
                {% endif %}
                {% if doc.cost_center %}
                <div class="mb-10">
                    <div><span class="text-strong">Centre de coût :</span> {{ doc.cost_center }}</div>
                </div>
                {% endif %}
            </div>
        </div>

        <!-- Flags abonnement (options actives) -->
        {%- set flags = [] -%}
        {%- if doc.cancel_at_period_end -%}{%- set _ = flags.append("Annulation en fin de période") -%}{%- endif -%}
        {%- if doc.follow_calendar_months -%}{%- set _ = flags.append("Suit les mois calendaires") -%}{%- endif -%}
        {%- if doc.generate_new_invoices_past_due_date -%}{%- set _ = flags.append("ERPnext continue de générer les factures, même en cas d'implayées ou retard.") -%}{%- endif -%}
        {%- if doc.submit_invoice -%}{%- set _ = flags.append("Soumettre les factures générées") -%}{%- endif -%}
        {% if flags %}
        <div class="row mb-10">
            <div class="col-xs-12">
                {%- for flag in flags -%}
                    <span class="tag">{{ flag }}</span>
                {%- endfor -%}
            </div>
        </div>
        {% endif %}

        <!-- Modèles de taxes -->
        {% if doc.sales_tax_template or doc.purchase_tax_template %}
        <div class="row mb-10">
            <div class="col-xs-12">
                {% if doc.sales_tax_template %}
                    <span class="small"><span class="text-strong">Taxes vente :</span> {{ doc.sales_tax_template }}</span>
                    {% if doc.purchase_tax_template %}&nbsp;&nbsp;{% endif %}
                {% endif %}
                {% if doc.purchase_tax_template %}
                    <span class="small"><span class="text-strong">Taxes achat :</span> {{ doc.purchase_tax_template }}</span>
                {% endif %}
            </div>
        </div>
        {% endif %}

        <!-- Adresse client -->
        <div class="row mb-10" style="display: flex;">
            <div class="col-xs-6 pl-4" style="margin-left: auto;">
                <div class="box">
                    <div class="text-strong" style="margin-bottom:2px;">Adresse de facturation :</div>

                    <div class="small"><strong>Nom :</strong> {{ customer_name_display or doc.party }}</div>

                    {% if billing_addr %}
                        {% if billing_addr.address_line1 or billing_addr.address_line2 %}
                            <div class="small"><strong>Adresse :</strong> {{ billing_addr.address_line1 or "" }} {{ billing_addr.address_line2 or "" }}</div>
                        {% endif %}
                        {% if billing_addr.city or billing_addr.country %}
                            <div class="small"><strong>Ville / Pays :</strong> {{ billing_addr.city or "" }} {{ billing_addr.country or "" }}</div>
                        {% endif %}
                        {% if billing_addr.phone %}
                            <div class="small"><strong>Tél :</strong> {{ billing_addr.phone }}</div>
                        {% endif %}
                        {% if billing_addr.email_id %}
                            <div class="small"><strong>Email :</strong> {{ billing_addr.email_id }}</div>
                        {% endif %}
                    {% endif %}

                    {% if doc.party_type == "Customer" %}
                        {% set customer_ncc = frappe.db.get_value('Customer', doc.party, 'tax_id') %}
                        {% if customer_ncc %}<div class="small"><strong>NCC :</strong> {{ customer_ncc }}</div>{% endif %}

                        {% set customer_regime = frappe.db.get_value('Customer', doc.party, 'custom_regime_dimposition') %}
                        {% if customer_regime %}<div class="small"><strong>Régime d'imposition :</strong> {{ customer_regime }}</div>{% endif %}

                        {% set customer_rccm = frappe.db.get_value('Customer', doc.party, 'custom_rccm') %}
                        {% if customer_rccm %}<div class="small"><strong>RCCM :</strong> {{ customer_rccm }}</div>{% endif %}
                    {% endif %}
                </div>
            </div>
        </div>

        <!-- Période de facturation courante -->
        {% if doc.current_invoice_start or doc.current_invoice_end %}
        <div class="row mb-10">
            <div class="col-xs-12">
                <div style="display:flex; gap:8px; align-items:flex-start;">
                    <strong style="min-width:120px;">Période de facturation :</strong>
                    <div>
                        {% if doc.current_invoice_start %}{{ frappe.utils.format_date(doc.current_invoice_start, "dd MMMM yyyy") }}{% endif %}
                        {% if doc.current_invoice_start and doc.current_invoice_end %} au {% endif %}
                        {% if doc.current_invoice_end %}{{ frappe.utils.format_date(doc.current_invoice_end, "dd MMMM yyyy") }}{% endif %}
                    </div>
                </div>
            </div>
        </div>
        {% endif %}

        <!-- Période d'essai -->
        {% if doc.trial_period_start and doc.trial_period_end %}
        <div class="row mb-10">
            <div class="col-xs-12">
                <div style="display:flex; gap:8px; align-items:flex-start;">
                    <strong style="min-width:120px;">Période d'essai :</strong>
                    <div>
                        {{ frappe.utils.format_date(doc.trial_period_start, "dd MMMM yyyy") }}
                        au
                        {{ frappe.utils.format_date(doc.trial_period_end, "dd MMMM yyyy") }}
                    </div>
                </div>
            </div>
        </div>
        {% endif %}

        <!-- Table des plans d'abonnement -->
        <div class="section-title">Plans d'abonnement</div>
        <table class="table table-bordered table-condensed" style="margin-top: 3px;">
            <colgroup>
                <col style="width:4%">
                <col style="width:28%">
                <col style="width:25%">
                <col style="width:15%">
                <col style="width:7%">
                <col style="width:21%">
            </colgroup>
            <thead>
                <tr>
                    <th class="text-center">N°</th>
                    <th>Plan d'abonnement</th>
                    <th>Description</th>
                    <th class="text-right">Prix unitaire</th>
                    <th class="text-center">Qté</th>
                    <th class="text-right">Montant</th>
                </tr>
            </thead>
            <tbody>
                {% for plan in doc.plans %}
                    {%- set plan_doc = frappe.get_cached_doc("Subscription Plan", plan.plan) if plan.plan else None -%}
                    {%- set plan_cost = frappe.db.get_value('Subscription Plan', plan.plan, 'cost') or 0 -%}
                    {%- set plan_qty = (plan.qty or 1)|int -%}
                    {%- set plan_amount = plan_cost * plan_qty -%}

                    {# Infos supplémentaires du plan #}
                    {%- set plan_item = plan_doc.item if plan_doc and plan_doc.get("item") else None -%}
                    {%- set plan_price_det = plan_doc.price_determination if plan_doc and plan_doc.get("price_determination") else None -%}
                    {%- set plan_price_list = plan_doc.price_list if plan_doc and plan_doc.get("price_list") else None -%}
                    {%- set plan_currency = plan_doc.currency if plan_doc and plan_doc.get("currency") else None -%}
                    {%- set plan_gateway = plan_doc.payment_gateway if plan_doc and plan_doc.get("payment_gateway") else None -%}
                    {%- set plan_product_id = plan_doc.product_price_id if plan_doc and plan_doc.get("product_price_id") else None -%}
                    {%- set plan_bi_count = plan_doc.billing_interval_count if plan_doc and plan_doc.get("billing_interval_count") else None -%}
                    {%- set plan_bi = plan_doc.billing_interval if plan_doc and plan_doc.get("billing_interval") else None -%}
                    {%- set plan_bi_label = ((plan_bi_count|string ~ " ") if plan_bi_count and plan_bi_count > 1 else "") ~ interval_map.get(plan_bi, plan_bi or "") if plan_bi else None -%}

                    <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                        <td class="text-center">{{ loop.index }}</td>
                        <td>
                            <div class="text-strong">{{ plan.plan }}</div>

                        </td>
                        <td>
                         {%    if plan.custom_description %}
                                <div class="desc">{{ plan.custom_description }}</div>
                          {% endif %}

                        </td>
                        <td class="text-right">{{ fmt_amount(plan_cost, doc.currency) }}</td>
                        <td class="text-center">{{ plan_qty }}</td>
                        <td class="text-right text-strong">{{ fmt_amount(plan_amount, doc.currency) }}</td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>

        <!-- Totaux -->
        <div class="row" style="margin-top:6px;">
            <div class="col-xs-6 col-xs-offset-6">
                <table class="totaux-table" style="width:100%; border:1.2px solid var(--accent);">
                    <tr>
                        <td>Sous-total</td>
                        <td class="text-right">{{ fmt_amount(total_ht.value, doc.currency) }}</td>
                    </tr>
                    {% if remise_montant.value > 0 %}
                    <tr style="color:#d97706;">
                        <td>
                            Remise
                            {% if remise_pct > 0 %} ({{ remise_pct }}%){% endif %}
                        </td>
                        <td class="text-right">- {{ fmt_amount(remise_montant.value, doc.currency) }}</td>
                    </tr>
                    <tr style="background:var(--accent); color:#fff;">
                        <td class="text-strong" style="color:#fff;">Total net par période</td>
                        <td class="text-right text-strong" style="color:#fff; font-size:11px;">{{ fmt_amount(total_net, doc.currency) }}</td>
                    </tr>
                    {% else %}
                    <tr style="background:var(--accent); color:#fff;">
                        <td class="text-strong" style="color:#fff;">Total par période</td>
                        <td class="text-right text-strong" style="color:#fff; font-size:11px;">{{ fmt_amount(total_ht.value, doc.currency) }}</td>
                    </tr>
                    {% endif %}
                </table>
            </div>
        </div>

        <!-- Montant en lettres -->
        <div class="small" style="font-style:italic; margin-top: 12px !important;">
            Arrêté à la somme de :
            <strong style="text-transform: capitalize;">{{ montant_fr(total_net) }}</strong>
        </div>

        <!-- Historique des factures générées -->
        {% if doc.invoices and doc.invoices|length > 0 %}
        <div style="margin-top:8px;">
            <div class="section-title">Factures générées</div>
            <table class="table table-bordered schedule-table">
                <thead>
                    <tr>
                        <th class="text-center">N° Facture</th>
                        <th class="text-center">Type</th>
                        <th class="text-center">Statut de paiement</th>
                    </tr>
                </thead>
                <tbody>
                {% for inv in doc.invoices %}
                    <tr class="{% if loop.index % 2 == 0 %}row-alt{% endif %}">
                        <td class="text-center text-strong">{{ inv.invoice or "—" }}</td>
                        <td class="text-center">{{ inv.document_type or "Sales Invoice" }}</td>
                        <td class="text-center">
                            {%- if inv.payment_status == "Paid" -%}
                                <span style="color:#16a34a; font-weight:700;">Payée</span>
                            {%- elif inv.payment_status == "Unpaid" -%}
                                <span style="color:#dc2626; font-weight:700;">Non payée</span>
                            {%- elif inv.payment_status == "Overdue" -%}
                                <span style="color:#d97706; font-weight:700;">En retard</span>
                            {%- elif inv.payment_status == "Partly Paid" -%}
                                <span style="color:#7c3aed; font-weight:700;">Partiellement payée</span>
                            {%- else -%}
                                {{ inv.payment_status or "—" }}
                            {%- endif -%}
                        </td>
                    </tr>
                {% endfor %}
                </tbody>
            </table>
        </div>
        {% endif %}

        <!-- Signature -->
        <div class="signature-box">
            <div class="signature-title">Bon pour accord</div>
            <div style="display:flex; gap:15px; font-size:8.5px;">
                <div>Date :</div>
                <div>Signature / Cachet :</div>
            </div>
            <div class="signature-space"></div>
        </div>

        <!-- FOOTER FIXE -->
        <div class="custom-footer">
            <div style="margin-bottom:2px;">
                <strong>S.A.R.L au capital de {{ capital_social }}</strong>
            </div>
            <div style="margin-bottom:2px;">
                {% if company.phone_no %}Tél : {{ company.phone_no }}{% endif %}
                {% if rccm %} &nbsp;|&nbsp; <strong>RCCM :</strong> {{ rccm }}{% endif %}
                {% if bank_info %} &nbsp;|&nbsp; <strong>{{ bank_info }}</strong>{% endif %}
            </div>
            {% if company.website %}
                <div><a href="{{ company.website }}">{{ company.website }}</a></div>
            {% endif %}
        </div>

    </div>
</div>
{% endfor %}

